	// 舱位不存在。
	se = requireError(t, func() error {
		_, err := r.Adjust("A2", []Op{{Kind: OpLoad, CargoID: "G1", Target: "CX"}})
		return err
	}(), ErrNotFound)
	if se.ID != "CX" {
		t.Fatalf("应指出不存在的舱位，实际 ID=%q", se.ID)
	}
	// 正常装载。
	if _, err := r.Adjust("A3", []Op{{Kind: OpLoad, CargoID: "G1", Target: "C1"}}); err != nil {
